mapper.select:
SELECT p.id, p.dept_id, d.dept_code, d.dept_name, p.post_code, p.post_name, p.status, (vpe.id IS NOT NULL) AS effective, p.order_num, p.remark, p.created_at, p.updated_at, p.created_by, p.updated_by FROM sys_post p INNER JOIN sys_dept d ON p.dept_id = d.id LEFT JOIN v_post_effective vpe ON vpe.id = p.id
AND p.post_code LIKE CONCAT('%', #{query.postCode}, '%')
AND p.post_name LIKE CONCAT('%', #{query.postName}, '%')
AND d.dept_name LIKE CONCAT('%', #{query.deptName}, '%')
AND p.status = #{query.status}
ORDER BY ${orderBySql}

SELECT p.id, p.dept_id, d.dept_name, p.post_code, p.post_name, p.status FROM sys_post p INNER JOIN sys_dept d ON p.dept_id = d.id
AND EXISTS ( SELECT 1 FROM v_post_effective vpe WHERE vpe.id = p.id )
AND p.status = #{status}
AND ( p.post_code LIKE CONCAT(#{keyword}, '%') OR p.post_name LIKE CONCAT(#{keyword}, '%') )
ORDER BY p.order_num, p.id DESC LIMIT #{limit}

SELECT
p.dept_id,
p.post_code
FROM
sys_post p
WHERE
(

    (
    p.dept_id = #{pair.deptId}
    AND p.post_code = #{pair.postCode}
    )

)
